      "question": "A urethane-forming step-growth reaction proceeds through a reversible complex: $\\ce{-NCO + -OH <=>[{k_1}][{k_{-1}}] Complex}$ and $\\ce{Complex + -OH ->[{k_2}] product + -OH}$. Using a steady-state approximation for the complex, which rate law best explains third-order behavior at low $[\\ce{OH}]$ and second-order behavior at high $[\\ce{OH}]$?",
