      "longAnswer": "(a) Micelles have a much higher surface area to volume ratio than monomer droplets since micelles are much smaller. Micelles therefore have a greater probability of receiving soap-like anionic free radicals. (b) The number of micelles per unit volume of aqueous phase is much more than the number of monomer droplets per unit volume, typical values being 10^18 versus 10^11. The monomer droplets can thus be considered to serve primarily as reservoirs of monomer and the number of free radicals that might be captured by them can be conveniently ignored.",
