      "datasetLabel": "ITPSC Certification",
      "type": "MCQ",
      "topic": "Thermodynamics of Binary Polymer Mixtures",
      "originalTopic": "Thermodynamics of Binary Polymer Mixtures",
      "subtopic": "molecular weight determination",
      "question": "A dilute polymer solution contains multiple monodisperse species $i$ with mass concentration $c_i$ and molecular weight $M_i$. If the osmotic pressure contributions add as $\\Pi = RT \\sum_i (c_i/M_i)$ and an osmotic molecular weight $M_{\\text{osm}}$ is defined by $\\Pi = RTc/M_{\\text{osm}}$ with $c = \\sum_i c_i$, which molecular-weight average does $M_{\\text{osm}}$ equal?",
