      "longAnswer": "For a dilute solution containing monodisperse species $i$, $\\Pi = RT \\sum_i (c_i/M_i)$. Defining $M_{\\text{osm}}$ by $\\Pi = RTc/M_{\\text{osm}}$ with $c = \\sum_i c_i$ gives $M_{\\text{osm}} = c/\\sum_i (c_i/M_i)$. Since the concentrations are proportional to weight fractions, $M_{\\text{osm}} = 1/\\sum_i (w_i/M_i)$, which is the definition of $\\bar{M}_n$. Therefore the osmotic molecular weight equals the number-average molecular weight.",
