      "question": "Starting from the solvent chemical-potential relation $\\mu_1 - \\mu_1^0 = RT \\ln a_1$, express the difference in chemical potential of the solvent in solution and in the pure state in terms of the solute mass concentration $c_2$ for dilute solutions. Use the dilute-solution approximations $a_1 \\approx x_1$, $x_1 = 1 - x_2$, and $\\ln(1 - x) = -x - x^2/2 - x^3/3 - \\cdots$. Let $V_1$ be the solvent molar volume, $M_1$ the solvent molar mass, and $M_2$ the solute molar mass. Which of the following series expressions is correct?",
      "options": {
        "A": "$\\mu_1 - \\mu_1^0 = -RTV_1\\left[c_2/M_2 + (V_1/(2M_2^2))c_2^2 + (V_1^2/(3M_2^3))c_2^3 + \\cdots\\right]$",
        "B": "$\\mu_1 - \\mu_1^0 = +RTV_1\\left[c_2/M_2 + (V_1/(2M_2^2))c_2^2 + (V_1^2/(3M_2^3))c_2^3 + \\cdots\\right]$",
        "C": "$\\mu_1 - \\mu_1^0 = -RTV_1\\left[c_2/M_2 + (V_1/M_2^2)c_2^2 + (V_1^2/M_2^3)c_2^3 + \\cdots\\right]$",
        "D": "$\\mu_1 - \\mu_1^0 = -RTV_1\\left[c_2/M_1 + (V_1/(2M_1^2))c_2^2 + (V_1^2/(3M_1^3))c_2^3 + \\cdots\\right]$"
      },
      "answer": "A",
      "longAnswer": "For a dilute solution, $a_1 \\approx x_1$, so $\\mu_1 - \\mu_1^0 \\approx RT \\ln x_1$. Since $x_1 = 1 - x_2$ and $x_2 \\ll 1$, $\\ln x_1 = \\ln(1 - x_2) = -x_2 - x_2^2/2 - x_2^3/3 - \\cdots$. If $c_2$ is the mass concentration of solute and $M_2$ its molar mass, then the solute molar concentration is $C_2 = c_2/M_2$. For dilute solution, the solvent molar concentration is approximately $C_1 \\approx 1/V_1$, so $x_2 \\approx C_2/C_1 = c_2 V_1/M_2$. Substituting into the series gives $\\mu_1 - \\mu_1^0 = -RTV_1[c_2/M_2 + (V_1/(2M_2^2))c_2^2 + (V_1^2/(3M_2^3))c_2^3 + \\cdots]$.",
