        "D": "$\\Delta \\overline{G}_1/(RT) = \\ln \\phi_1 + (1 - 1/\\sigma)\\phi_2 + [\\chi_{12} - \\phi_1(\\partial \\chi_{12}/\\partial \\phi_2)_{P,T}]\\phi_2^2$",
        "E": "$\\Delta \\overline{G}_1/(RT) = \\ln \\phi_1 + (1 - 1/\\sigma)\\phi_1 + [\\chi_{12} - \\phi_1(\\partial \\chi_{12}/\\partial \\phi_2)_{P,T}]\\phi_2^2$"
