      "type": "MCQ",
      "topic": "Thermodynamics of Binary Polymer Mixtures",
      "originalTopic": "Thermodynamics of Binary Polymer Mixtures",
      "subtopic": "molecular weight determination",
      "question": "For a polydisperse polymer at infinite dilution, let the turbidity of species $i$ be $\\tau_i = H c_i M_i$, where $H$ is an optical constant, $c_i$ is the mass concentration, and $M_i$ is the molecular weight. If turbidity is additive, $\\tau = \\sum_i \\tau_i$, and the measured molecular weight is defined by $\\tau = H c M$ with $c = \\sum_i c_i$, which of the following expressions is correct?",
      "options": {
        "A": "$M = (\\sum_i c_i M_i)/(\\sum_i c_i) = (\\sum_i N_i M_i^2)/(\\sum_i N_i M_i) = M_w$",
        "B": "$M = (\\sum_i c_i M_i)/(\\sum_i c_i) = (\\sum_i N_i M_i)/(\\sum_i N_i) = M_n$",
        "C": "$M = (\\sum_i c_i)/(\\sum_i (c_i/M_i)) = (\\sum_i N_i M_i)/(\\sum_i N_i) = M_n$",
        "D": "$M = (\\sum_i c_i M_i^2)/(\\sum_i c_i M_i) = (\\sum_i N_i M_i^3)/(\\sum_i N_i M_i^2) = M_z$"
      },
      "answer": "A",
      "longAnswer": "At infinite dilution, the total turbidity is additive: $\\tau = \\sum_i \\tau_i = H \\sum_i c_i M_i$. Defining the measured molecular weight by $\\tau = H c M$ with $c = \\sum_i c_i$ gives $M = (\\sum_i c_i M_i)/(\\sum_i c_i)$. Since $c_i = N_i M_i/V$, where $N_i$ is the amount of species $i$ in solution volume $V$, substitution gives $M = (\\sum_i N_i M_i^2)/(\\sum_i N_i M_i)$. This is exactly the definition of the weight-average molecular weight $M_w$. Therefore, the molecular weight obtained by light scattering is $M_w$.",
      "reference": "page_187, problem 4.13",
      "keywords": [
        "light scattering",
        "weight-average molecular weight",
        "Mw",
        "polydispersity"
      ],
      "ability": [
        "knowledge",
        "reasoning"
      ],
      "metrics": [],
      "outputDescription": [
        "proof that light-scattering molecular weight equals Mw"
      ],
      "outputUnit": [],
      "images": []
