      "id": "dc3c3ab8-7483-4a45-9bd5-54983fe40c4e",
      "dataset": "pst",
      "datasetLabel": "Polymer Science Textbook",
      "type": "MCQ",
      "topic": "Polymer Properties",
      "originalTopic": "Polymer Properties",
      "subtopic": "Thermal properties",
      "question": "Isotactic poly(methyl methacrylate) exhibits a significantly lower glass transition temperature than its syndiotactic counterpart. Which explanation best accounts for the higher Tg of the syndiotactic polymer?",
      "options": {
        "A": "Isotactic PMMA has more compact chain packing due to regular side-group placement, restricting segmental motion",
        "B": "Syndiotactic PMMA has stronger intermolecular interactions and higher backbone bending energy compared to isotactic PMMA",
        "C": "Syndiotactic PMMA has lower crystallinity, resulting in more rigid amorphous regions with restricted chain mobility",
        "D": "Isotactic PMMA undergoes partial crystallization that plasticizes the remaining amorphous phase, lowering Tg",
        "E": "Syndiotactic PMMA has higher molecular weight due to slower propagation rates during low-temperature free-radical polymerization"
      },
      "answer": "B",
      "longAnswer": "**Polymerization methods:** - **Syndiotactic PMMA** can be obtained by free-radical polymerization at low temperatures (T. G. Fox et al., *JACS* **80**, 1768 (1958); F. A. Bovey, *JPS* **46**, 69 (1960)). - Both **syndiotactic and isotactic** polymers can be obtained from **anionic polymerizations** using appropriate catalysts and conditions. **Explanation for $T_g$ difference:** Recent molecular modeling (A. Soldera, *Polymer* **43**, 4269 (2002)) indicates that differences in both: 1. **Intermolecular interactions** - The syndiotactic configuration allows for stronger intermolecular packing and interactions between chains 2. **Bending angle energy along the backbone** - The syndiotactic arrangement results in higher conformational barriers These factors can be correlated with the **higher $T_g$ of the syndiotactic polymer**. The isotactic polymer has more chain mobility due to less efficient packing and lower rotational barriers, resulting in a lower glass transition temperature.",
