      "question": "The dielectric loss constant of a polymer is described by $\\varepsilon^{\\prime\\prime} = \\frac{\\omega\\tau(\\varepsilon_R - \\varepsilon_U)}{1 + \\omega^2\\tau^2}$, where the relaxation time follows $\\tau = \\tau_o \\exp(H/RT)$ and $H$ is the activation energy. The maximum in $\\varepsilon^{\\prime\\prime}$ occurs at $T_{\\max}$ where $\\omega = 1/\\tau$. Given experimental data of $\\varepsilon^{\\prime\\prime}$ versus temperature at several frequencies $f$, which procedure correctly determines $H$?",
