      "id": "14f788a7-04fc-4331-b768-cfb42229b565",
      "dataset": "renzheng",
      "datasetLabel": "Certification Review",
      "type": "MCQ",
      "topic": "Polymerization Synthesis",
      "originalTopic": "polymer_chemistry",
      "subtopic": "polymerization_kinetics",
      "question": "For an externally acid-catalyzed step-growth polymerization of an equimolar diol + diacid mixture, an integrated form relating time t and extent of reaction p is t = p/(k'$[M]$0(1-p)). Using this relation, which statement best compares the additional time needed to increase conversion from p = 0.98 to p = 0.99 with the time required to reach p = 0.98 from the start?",
      "options": {
        "A": "The additional time from 0.98 to 0.99 is much smaller than the time to reach 0.98 (less than $\\pu{10\\%}$ of it).",
        "B": "The additional time from 0.98 to 0.99 is approximately equal to the time to reach 0.98.",
        "C": "The additional time from 0.98 to 0.99 is approximately twice the time to reach 0.98.",
        "D": "The additional time from 0.98 to 0.99 is approximately half the time to reach 0.98.",
        "E": "The additional time from 0.98 to 0.99 is exactly zero because p is already high."
      },
      "answer": "B",
      "longAnswer": "$[M]$0 k' t = 1/(1 - p) - 1 = p/(1 - p) t = p / (k' $[M]$0 (1 - p)) For p = 0.98, t0.98 = 0.98 / 0.02k'$[M]$0 = 49/k'$[M]$0 For p = 0.99, t0.99 = 0.99 / 0.01k'$[M]$0 = 99/k'$[M]$0 t0.99 - t0.98 = 50/k'$[M]$0 $\\approx$ t0.98",
