      "originalTopic": "Polymerization Synthesis",
      "subtopic": "Copolymerization (random, segmented, block copolymers)",
      "question": "The sequence-length distributions for the two cases below are shown in <image_1>. For an ideal copolymerization with equimolar feed composition, take $f_1 = f_2 = 0.5$, define $P_{11} = r_1 f_1/(r_1 f_1 + f_2)$, $P_{12} = 1 - P_{11}$, $P_{22} = r_2 f_2/(r_2 f_2 + f_1)$, and $P_{21} = 1 - P_{22}$. Use $n_x(M_1) = P_{12}P_{11}^{x-1}$ and $n_x(M_2) = P_{21}P_{22}^{x-1}$ for the mole fractions of sequences of length $x$, and report mole percentages as $100\\,n_x$. Report the mole percentages for the following cases: (a) $r_1 = r_2 = 1$ and (b) $r_1 = 5$, $r_2 = 0.2$. In case (a), report the mole percentages of $M_1$ sequences of lengths 1 through 7; the $M_2$ distribution is identical and need not be repeated. In case (b), report the mole percentages of $M_1$ sequences of lengths 1 through 7 and of $M_2$ sequences of lengths 1 through 4. Report all percentages to three significant figures.",
      "options": {},
      "answer": [
        50.0,
        25.0,
        12.5,
        6.25,
        3.13,
        1.56,
        0.78,
        16.7,
        14.0,
        11.6,
        9.7,
        8.1,
        6.7,
        5.6,
        83.3,
        13.9,
        2.3,
        0.39
      ],
      "longAnswer": "(a) For the system $r_1 = r_2 = 1$ with $f_1 = 0.5$, the ideal-copolymerization relations give $P_{11} = P_{12} = P_{22} = P_{21} = 0.50$. The values of $n_x(M_1)$ are 0.50, 0.25, 0.125, 0.0625, 0.0313, 0.0156, and 0.0078 for sequences with 1, 2, 3, 4, 5, 6, and 7 $M_1$ units, respectively. Thus, the corresponding percentages are $\\pu{50.0\\%}$, $\\pu{25.0\\%}$, $\\pu{12.5\\%}$, $\\pu{6.25\\%}$, $\\pu{3.13\\%}$, $\\pu{1.56\\%}$, and $\\pu{0.78\\%}$. The distribution of $M_2$ sequences is exactly the same as for $M_1$ sequences. (b) For the system $r_1 = 5$, $r_2 = 0.2$ with $f_1 = 0.5$, the relations give $P_{11} = P_{21} = 0.8333$ and $P_{12} = P_{22} = 0.1667$. The values of $n_x(M_1)$ are 0.167, 0.140, 0.116, 0.097, 0.081, 0.067, and 0.056 for sequences with 1 through 7 $M_1$ units, corresponding to $\\pu{16.7\\%}$, $\\pu{14.0\\%}$, $\\pu{11.6\\%}$, $\\pu{9.7\\%}$, $\\pu{8.1\\%}$, $\\pu{6.7\\%}$, and $\\pu{5.6\\%}$. The less reactive $M_2$ monomer gives a much narrower distribution: single $M_2$ units are by far the most plentiful at $\\pu{83.3\\%}$, followed by $\\pu{13.9\\%}$ dyads, $\\pu{2.3\\%}$ triads, and $\\pu{0.39\\%}$ tetrads.",
      "reference": "page_402, problem 7.9",
