      "topic": "Polymerization Synthesis",
      "originalTopic": "Polymerization Synthesis",
      "subtopic": "Chain-growth polymerization",
      "question": "In a low-temperature polymerization of isobutylene using $\\ce{TiCl4}$ as catalyst and $\\ce{H2O}$ as cocatalyst, the following results were obtained at $\\pu{-35 ^\\circ C}$ showing the effect of monomer concentration on the average degree of polymerization: $[\\ce{C4H8}]$ values (in $\\pu{mol L^{-1}}$) = 0.667, 0.333, 0.278, 0.145, 0.059 and $\\overline{DP}_n$ = 6940, 4130, 2860, 2350, 1030. The corresponding plot of $1/\\overline{DP}_n$ versus $1/[\\ce{C4H8}]$ is shown in <image_1>. Neglect spontaneous termination and any chain-transfer agent, and use $1/\\overline{DP}_n = (k_t/k_p)(1/[M]) + C_M$ with $C_M = k_{tr,M}/k_p$. Use the textbook straight-line estimates from <image_1>, which give slope $k_t/k_p = \\pu{5.0e-5 mol L^{-1}}$ and intercept $C_M = k_{tr,M}/k_p = 1.1 \\times 10^{-4}$. Determine $k_t/k_p$ and $k_{tr,M}/k_p$. Report both quantities to two significant figures.",
      "options": {},
      "answer": [
        5e-05,
        0.00011
      ],
      "longAnswer": "In a plot of $(1/\\overline{DP}_n) \\times 10^4$ versus $1/[M]$, the plotted slope equals $(k_t/k_p) \\times 10^4$. The slope is about $0.50$, so $k_t/k_p = 0.50 \\times 10^{-4} = \\pu{5.0e-5 mol L^{-1}}$. The intercept gives $C_M = k_{tr,M}/k_p = 1.1 \\times 10^{-4}$.",
      "reference": "page_478, problem 8.23",
