      "subtopic": "dilute polymer solutions",
      "question": "Find the osmotic pressure of a solution of $\\pu{1.0 g}$ glucose ($\\ce{C6H12O6}$, molar mass $\\pu{180.16 g mol^{-1}}$) in $\\pu{1000 cm^3}$ of water at $\\pu{25 ^\\circ C}$. <image_1> Assume ideal dilute behavior and use $\\Pi = nRT/V$ with $R = \\pu{82.06 cm^3 atm mol^{-1} K^{-1}}$ and $T = \\pu{298 K}$. Report $\\Pi$ to three significant figures in atm and to one decimal place in torr.",
      "options": {},
      "answer": [
        0.136,
        103.2
      ],
      "longAnswer": "The molar mass of glucose is $\\pu{180.16 g mol^{-1}}$, so the number of moles of solute is $n_B = 1.0/180.16 = 0.0055506\\,\\pu{mol}$. For ideal dilute behavior, $\\Pi = n_BRT/V$. With $V = \\pu{1000 cm^3}$, $R = \\pu{82.06 cm^3 atm mol^{-1} K^{-1}}$, and $T = \\pu{298 K}$, $\\Pi = (0.0055506)(82.06)(298)/1000 = \\pu{0.135734 atm}$, which rounds to $\\pu{0.136 atm}$. In torr, $\\Pi = 0.135734 \\times 760 = \\pu{103.2 torr}$.",
      "reference": "page_172, problem 4.6",
      "keywords": [
        "osmotic pressure",
        "glucose",
        "dilute solution"
      ],
