      "type": "QA",
      "topic": "Thermodynamics of Binary Polymer Mixtures",
      "originalTopic": "Thermodynamics of Binary Polymer Mixtures",
      "subtopic": "Flory-Huggins theory and phase diagram",
      "question": "A neoprene rubber vulcanizate containing $\\pu{90 \\%}$ by weight chloroprene has $\\pu{1 \\%}$ of the chloroprene units crosslinked. The interaction parameter $\\chi$ of the polymer in $n$-hexane is 1.13. Data: rubber density $= \\pu{1.23 g cm^{-3}}$ and molar volume of $n$-hexane at $\\pu{25 ^\\circ C}$ $= \\pu{131.6 cm^3 mol^{-1}}$. The graphical solution of the swelling-equilibrium equation for this system is shown in <image_1>. From the plot, take the intersection at $\\phi_{2m} \\approx 0.757$. Calculate the maximum swelling, expressed as volume of solvent imbibed per unit volume of the vulcanizate, using $(1 - \\phi_{2m})/\\phi_{2m}$. Report the result to two decimal places.",
      "options": {},
      "answer": [
        0.32
      ],
      "longAnswer": "The equilibrium polymer volume fraction in the swollen state is $\\phi_{2m} \\approx 0.757$. The maximum solvent uptake per unit dry polymer volume is $(1/\\phi_{2m}) - 1 = (1/0.757) - 1 \\approx 0.32\\,\\pu{vol/vol}$. Equivalently, the vulcanizate swells to $1/0.757 \\approx 1.32$ times its original volume, but the requested solvent uptake is $0.32\\,\\pu{vol/vol}$.",
      "reference": "page_140, problem 3.21",
