      "longAnswer": "\\nFrom the tabulated datas we take the following data (increments per structural unit): $\\begin{array}{lccc}\\n& Y_{mi} & Y_{gi} & M_i \\n\\text{unit 1} & 133 & 111 & 216.3 \\n\\text{unit 2} & 125 & 87 & 194.3 \\n2{-}\\ce{O}- & 27 & 8 & 32.0 \\n\\hline\\n\\text{sum} & 285 & 206 & 442.6\\n\\end{array}$ Hence $T_m = (285 \\times 10^3)/442.6 = \\pu{645 K}$, $T_g = (206 \\times 10^3)/442.6 = \\pu{466 K}$, $T_g/T_m = 0.71$. Literature data: $T_g = 465\\text{-}\\pu{499 K}$.",
