      "question": "Estimate the glass transition temperature of poly(ether-ether-ketone) (PEEK). Its repeating unit is: [START_SMILES]O=C(c1ccc(O)cc1)c1ccc(Oc2ccc(O)cc2)cc1[END_SMILES] <image_1> <image_2> <image_3>.",
      "options": {},
