      "question": "Estimate the glass transition temperature $T_g$ of the poly(imide) polymer ULTEM $1000$ (produced by General Electric Co). The formula of the structural unit (molar mass $M = 587$) is <image_1> <image_2> <image_3> <image_4>.",
