      "longAnswer": "\\nFrom the tabulated datas we derive the following increments: $2 Y_g\\left( \\begin{array}{c}\\n \\text{imide} \\n \\text{aromatic unit}\\n \\end{array} \\right) = 2 \\times 95 = 190$, $2 Y_g(-\\ce{O}-) = 2 \\times 4 = 8$, $Y_g\\left(\\begin{array}{c}\\n \\text{bisphenol-A-like} \\n \\text{unit}\\n \\end{array} \\right) = 87$. Thus $Y_g = 285$. The glass transition temperature is then $T_g = (285 \\times 1000)/578 = \\pu{493 K}$; the literature value is $\\pu{490 K}$. Other factors influencing the value of $T_g$ are discussed in the text.",
