      "question": "Estimate the decrease in the viscosity of a poly(ethylene terephthalate) melt at a shear rate of $\\pu{5000 s^-1}$. $Mw = 3.72 \\times 10^4 = \\pu{37.2 kg/mol}$; $Q = 3.5$; $T = \\pu{553 K}$; $\\eta0 = \\pu{156 N s/m^2}$; $\\rho = \\pu{1160 kg/m^3}$ <image_1>.",
