      "question": "Estimate the elastic parameters of poly(methyl methacrylate). The structural unit is [START_SMILES]*CC(C)(C(=O)OC)*[END_SMILES], with $M = \\pu{100.1 g/mol}$, $\\rho = \\pu{1.19 g/cm^3}$ and $V = \\pu{84.5 cm^3/mol}$ <image_1>.",
