      "datasetLabel": "Polymer Open Problems",
      "type": "QA",
      "topic": "Polymer Properties",
      "originalTopic": "Polymer properties",
      "subtopic": "Thermal properties",
      "question": "Estimate the characteristic temperatures of an LCP with mesogenic groups in main- and side-chain (structure ): <image_1> <image_2> <image_3>.",
      "options": {},
      "answer": [
        462,
        309,
        0.67,
        485
      ],
      "longAnswer": "The molar mass of the structural unit is $M = 667$; it consists of the following structural groups with the indicated group contributions: - 1 basic group $-\\ce{CH(CN)}-$: $Y_g = 11.5$, $Y_m = 17.5$ - 2 functional groups $-\\ce{COO}-$: $Y_g = 25$, $Y_m = 50$ - $2 \\times 2$ $\\ce{CH_2}-$ groups ($Y_m$ calculated according to the tabulated data): $Y_g = 10.8$, $Y_m = 4$ - 2 mesogenic units (see the tabulated data): $Y_g = 140$, $Y_m = 200$ - 2 functional linking groups $-\\ce{O}-$: $Y_g = 8$, $Y_m = 27$ - 6 inserted $-\\ce{CH_2}-$ groups in the side chain (use the stated relation and (6.22)-(6.24)): $Y_g = 10.5$, $Y_m = 9.1$ Thus $\\sum Y_g = 205.8, \\sum Y_m = 307.6$. For the characteristic temperatures the rounded values $Y_g = 206$ and $Y_m = 308$ are used: $T_m = 308/667 \\times 1000 = \\pu{462 K}$, $T_g = 206/667 \\times 1000 = \\pu{309 K}$, and $T_g/T_m = 0.67$. Finally, $T_i = 1.05 \\times 462 = \\pu{485 K}$.",
      "reference": "Example 6.10",
