      "longAnswer": "According to the included figure $\\varphi_p=0.85$ and $K=2.5$:$(T_{g2}-T_g)/(T_{g2}-T_{g1})=0.29$ For polystyrene $T_{g2}=\\pu{373 K}$. The value of $T_{g1}$ for benzyl alcohol cannot be found in the literature. So the estimated value is derived from $T_{m1}=\\pu{258 K}$:$T_{g1}=2/3T_{m1}=\\pu{172 K}$ With these data, the estimated value is $T_g=\\pu{315 K}$. The experimental value of Kambour et al. (1973) is $T_g=\\pu{324 K}$.",
