      "topic": "Polymer Processing",
      "originalTopic": "Polymer processing",
      "subtopic": "Nonisothermal polymer processing",
      "question": "As shown in Figure 5.1, a film of polypropylene (PP) of thickness $\\pu{0.1016 cm}$ is extruded from a die with a width of $\\pu{0.162 m}$ onto a casting drum $\\pu{2.54 cm}$ below the die. The film temperature as it leaves the die is $\\pu{200 ^\\circ C}$. The heat transfer coefficient is $\\pu{100 W/m^2\\cdot K}$. Neglect radiation and use an average film thickness of $\\pu{2.54 \\times 10^{-2} cm}$. The air temperature is $\\pu{25 ^\\circ C}$. Determine the temperature of the film surface when it contacts the casting drum.",
      "options": {},
      "answer": [
        199.9
      ],
      "longAnswer": "The model of the region to be analyzed is shown in Figure 5.3. The heat is removed primarily by forced convection at the surfaces due to air at $\\pu{25 ^\\circ C}$ moving over the sheet. An energy balance is performed on the differential element shown in Figure 5.3 to give $ V_0 \\rho \\bar{C}_p (T - T_R)|_x W \\Delta y - V_0 \\rho \\bar{C}_p (T - T_R)|_{x+\\Delta x} W \\Delta y - q_x|_x W \\Delta y + q_x|_{x+\\Delta x} W \\Delta y + (q_y|_y - q_y|_{y+\\Delta y}) W \\Delta x = 0 $ Taking the limit as $ \\Delta x, \\Delta y \\to 0 $ gives $ - V_0 \\rho \\bar{C}_p (\\partial T)/(\\partial x) - (\\partial q_x)/(\\partial x) - (\\partial q_y)/(\\partial y) = 0 $ Using Fourier’s law, $ q_x = -k (\\partial T)/(\\partial x), \\quad q_y = -k (\\partial T)/(\\partial y) $ Substitution gives $ V_0 \\rho \\bar{C}_p (\\partial T)/(\\partial x) - k (\\partial^2 T)/(\\partial x^2) - k (\\partial^2 T)/(\\partial y^2) = 0 $ Introducing the dimensionless quantities $ \\xi = x/b, \\quad \\zeta = y/b, \\quad \\theta = (T - T_a)/(T_0 - T_a) $ the equation becomes $ (b V_0 \\rho \\bar{C}_p)/k (\\partial \\theta)/(\\partial \\xi) = (\\partial^2 \\theta)/(\\partial \\xi^2) + (\\partial^2 \\theta)/(\\partial \\zeta^2) $ The term multiplying $ \\partial \\theta / \\partial \\xi $ is the Peclet number, Pe. Since Pe $ \\gg 1 $, the equation reduces to $ \\text{Pe} (\\partial \\theta)/(\\partial \\xi) = (\\partial^2 \\theta)/(\\partial \\zeta^2) $ Defining the mean temperature $ \\bar{\\theta} = \\int_{-1}^{1} \\theta \\, d\\zeta / \\int_{-1}^{1} d\\zeta $ and integrating across the thickness gives $ \\text{Pe} (d \\bar{\\theta})/(d \\xi) = - (h b)/k \\bar{\\theta} $ The solution is $ \\bar{\\theta} = e^{-C \\xi} $ where $ C = h/(\\rho \\bar{C}_p V_0) $. Using the material properties for PP from Table 5.4 and the conditions given in the problem, the solution gives $ \\theta = 0.999 $. Thus, the change in film temperature over a distance of $\\pu{2.54 cm}$ is insignificant. Therefore, the film surface temperature at the casting drum is approximately $ T \\approx \\pu{199.9 ^\\circ C} $.",
      "reference": "Example 5.1. Cooling of Polypropylene Film",
      "keywords": [
        "film-cooling",
        "forced-convection",
        "energy-balance",
        "peclet-number",
        "polypropylene-film"
      ],
      "ability": [
        "calculation"
      ],
      "metrics": [
        "exact_match"
      ],
      "outputDescription": [
        "Film surface temperature at drum contact"
      ],
      "outputUnit": [
        "\\pu{^\\circ C}"
      ],
      "images": []
