      "id": "79df313e-e792-4b61-b296-186b973b926a",
      "dataset": "pppd",
      "datasetLabel": "Polymer Processing Problems",
      "type": "QA",
      "topic": "Polymer Processing",
      "originalTopic": "Polymer processing",
      "subtopic": "Nonisothermal flow and viscous heating",
      "question": "Returning to Section 2.2.1 we now ask whether the melt temperature will remain as $\\pu{453 K}$ as HDPE passes through the pipe die at the upper extrusion limit. We assume that the melt enters the die at $ T_0 = \\pu{453 K} $ and that the wall temperature at $ r = R $ is also maintained at $\\pu{453 K}$. The rheological properties for this melt were given in Table 2.3. For this problem we take these properties to be independent of temperature: $ \\rho = \\pu{782 kg/m^3} $, $ C_p = \\pu{2650 J/kg\\cdot K} $, and $ k = \\pu{0.255 W/m\\cdot K} $. Determine the temperature rise at the exit of the die due to viscous dissipation.",
      "options": {},
      "answer": [
        14.6
      ],
      "longAnswer": "For pedagogical purposes we solve this problem using the forced convection assumption in which it is assumed that the velocity profile is unaffected by changes in the viscosity as a result of changes in temperature. With this assumption, the velocity profile remains unchanged from that of the isothermal case and the equation of motion can be used independently of the energy equation. The equation of motion for this problem was given in Eq. 2.10 and is repeated below: $ d/dr(r\\tau_{rz}) = -\\left(dp/dz\\right)r = (P_0 - P_L)/L r $ For a GNF model using the power-law empiricism for viscosity, the velocity field was given in Eqs. 2.28 and 2.29. Taking $ n = 0.5 $ (actually it is 0.56, but this allows us to obtain an analytical solution) we find $ v_z^* $ and $ v_z^{\\circ} $, respectively. We next carry out an energy balance on the differential element shown in Figure 5.5. The sources of energy transport consist of heat transfer into and out of the element by convection due to flow in the z direction, conduction of heat into and out of the element in both the z and r directions, and heat generated by viscous dissipation. When an energy balance is applied to the element shown in Figure 5.5 the following equation is obtained: $ \\rho \\bar{C}_p (T - T_R) v_z 2\\pi r \\Delta r - \\rho \\bar{C}_p (T - T_R) v_z|_{z+\\Delta z} 2\\pi r \\Delta r + (q_z|_z - q_z|_{z+\\Delta z}) 2\\pi r \\Delta r + (q_r|_r - q_r|_{r+\\Delta r}) 2\\pi r \\Delta z + \\dot{S} 2\\pi r \\Delta r \\Delta z = 0 $ Viscous dissipation is given by $ \\dot{S} = -\\tau_{rz} dv_z/dr $ Dividing through by the volume of the element and taking the limit as $ \\Delta r, \\Delta z \\to 0 $ leads to: $ \\rho \\bar{C}_p v_z (\\partial T)/(\\partial z) = (\\partial q_z)/(\\partial z) + 1/r \\partial/(\\partial r)(r q_r) + \\dot{S} $ Substituting Fourier’s law and the expression for viscous dissipation yields $ \\rho \\bar{C}_p v_z(r) (\\partial T)/(\\partial z) = k (\\partial^2 T)/(\\partial z^2) + k/r \\partial/(\\partial r)\\left(r (\\partial T)/(\\partial r)\\right) + m \\left| dv_z/dr \\right|^{n-1} \\left( dv_z/dr \\right)^2 $ Because of the forced convection assumption we neglect the axial conduction term and treat the annular die as a parallel plate geometry. Equation 5.48 becomes $ \\rho \\bar{C}_p v_z(y) (\\partial T)/(\\partial z) = k (\\partial^2 T)/(\\partial y^2) + m \\left| dv_z/dy \\right|^{n-1} \\left( dv_z/dy \\right)^2 $ Using the boundary and initial conditions and averaging over the cross-sectional area leads to $ \\rho \\bar{C}_p \\langle v_z \\rangle H W dT/dz = (W H m)/(s+2) \\left[ (v_{\\max}(s+1))/(H/2) \\right]^{n+1} $ which integrates to give $ T - T_0 = m/(\\rho \\bar{C}_p \\langle v_z \\rangle (s+2)) \\left[ (v_{\\max}(s+1))/(H/2) \\right]^{n+1} z $ Using the results from Section 2.2.2 and the values given in the problem statement, we find $ T - T_0 = \\pu{14.6 K} $ With the length of the die given as $\\pu{6.35 \\times 10^{-3} m}$, the temperature rise is only $\\pu{0.92 K}$. Hence, for the case at hand there is no significant rise in temperature as a result of viscous heating.",
      "reference": "Example 5.3. Nonisothermal Flow of HDPE Through a Pipe Die",
      "keywords": [
        "nonisothermal-flow",
        "pipe-die",
        "viscous-dissipation",
        "energy-balance",
        "temperature-rise"
      ],
      "ability": [
        "calculation"
      ],
      "metrics": [
        "exact_match"
      ],
      "outputDescription": [
        "temperature rise at die exit"
      ],
      "outputUnit": [
        "\\pu{K}"
      ],
      "images": []
