      "topic": "Polymer Processing",
      "originalTopic": "Polymer processing",
      "subtopic": "Single-screw extrusion",
      "question": "LDPE is extruded in a single-screw extruder having a diameter of $\\pu{6.35 cm}$ ($\\pu{6.35 \\times 10^{-2} m}$). The square pitch screw (i.e., L_s = D_b) is 26.5 turns long with a feed section of 12.5 turns and channel depth of $\\pu{9.398 \\times 10^{-3} m}$, a transition section of 9.5 turns, and a metering section $\\pu{3.22 \\times 10^{-3} m}$ deep. The flight width is $\\pu{6.35 \\times 10^{-3} m}$, and the flight clearance is negligible. The screw rotates at \\pu{60 rpm} and the mass flow rate is $\\pu{67.1 kg/h}$. The pellets enter the extruder at $\\pu{25 ^\\circ C}$ from the hopper described in Example 8.1. The hopper discharge opening is $\\pu{0.127 m}$ and occupies the first two turns of the screw. The barrel is maintained at $\\pu{149 ^\\circ C}$ and melting starts 3 turns beginning at the end of flights. The friction coefficients between the polymer and the barrel and the screw are 0.45 and 0.25, respectively. Calculate (a) the pressure at the end of the solids conveying zone (i.e., over 1 turn), (b) the power consumption in the solids conveying zone, and (c) the energy per unit surface area dissipated into heat.",
      "options": {},
      "answer": [
        252000.0,
        60.8,
        3.89
      ],
      "longAnswer": "We first compute some geometrical values required in the solids conveying model: \\phi_b, helix angle at barrel surface = 17.65 ^\\circ \\phi_s, mean helix angle = 20.48 ^\\circ \\phi_s, helix angle at root of screw = 24.33 ^\\circ W̄, mean channel width = \\pu{5.314 \\times 10^{-2} m} W_b, channel width at barrel surface = \\pu{5.416 \\times 10^{-2} m} W_s, channel width at root of screw = \\pu{5.151 \\times 10^{-2} m} l, axial length = 10.5 turns, \\pu{0.666 m} Z̄, mean helical length = \\pu{2.270 m} We next calculate the pressure rise from Eq. 8.27. To calculate P2/P1, we determine \\phi′ from Eq. 8.22, which in turn is used to calculate M and K_s. The axial velocity of the solid plug is $V_{p1}$ = (61.7/3600) / [(595)(\\pi/4)[(0.065)^2 − (0.0447)^2] − (0.00635)(0.009398)/sin(20.48 ^\\circ)] = \\pu{\\pu{0.02195 m}/s} The velocity of the barrel surface V_b = \\piND_b = \\pu{\\pu{0.19995 m}/s}, and hence from Eq. 8.22 we find tan \\phi′ = tan \\phi_b / (V_b/$V_{p1}$ tan \\phi_b − 1) = 0.1261 and \\phi′ = 7.57 ^\\circ. From Eq. 8.26 we find K_s: K_s = [(0.0541) sin(20.48 ^\\circ) + (0.25) cos(20.48 ^\\circ)] / [0.0635 cos(20.48 ^\\circ) − (0.25) sin(20.48 ^\\circ)] = 0.5859 and from Eq. 8.25 M = cos(7.57 ^\\circ) − 0.5859 sin(7.57 ^\\circ) = 0.9141 The pressure rise, P2/P1, over one turn of the solids conveying section (Z_b = 0.0635/sin 17.6 ^\\circ = \\pu{0.209 m}), which starts just after the two flights occupied by the hopper throat and ends with the heating of the barrel, is obtained from P2/P1 = 0.1676 + 0.34328 + 0.09813 ln(P2/P1) and this leads to P2/P1 = 60.9 P1 is the pressure at the base of the hopper, which was calculated in Example 8.1. Thus, P2 is \\pu{2.52 \\times 10^5 Pa} (\\pu{36.5 psi}). The power input through the barrel is obtained from Eq. 8.29 and is P_w = (\\pi)(1)(0.0635)(0.05416)(0.209)(0.45)cos(5.750) / [(2.52 \\times 10^5) − (4.131 \\times 10^3)]/ln(60.9) = 60.8 W The power dissipated into heat per unit surface area is obtained from Eq. 8.30 and is q_b = P_w(0.1995)(0.45)(sin(17.650))/sin(17.65 + 7.57) = 0.0639 P_w Using P_w = 60.8 W gives q_b = 3.89 W",
      "reference": "Example 8.2. Solids Conveying of LDPE (Tadmor and Gogos, 1979)",
      "keywords": [
        "solids-conveying",
        "single-screw-extruder",
        "pressure-rise",
        "power-consumption",
        "energy-dissipation",
        "ldpe-extrusion"
      ],
