      "id": "93a4a881-15f0-46ae-a6cf-4eac131bca82",
      "dataset": "pppd",
      "datasetLabel": "Polymer Processing Problems",
      "type": "QA",
      "topic": "Polymer Properties",
      "originalTopic": "Polymer properties",
      "subtopic": "Diffusion and permeability",
      "question": "Estimate the diffusivity of oxygen in polycarbonate at $\\pu{298 K}$.",
      "options": {},
      "answer": [
        1.8e-08
      ],
      "longAnswer": "The collision diameter of oxygen is $\\pu{34.67 nm}$ (from Table 4.8) and the glass transition temperature of polycarbonate (PC) is $\\pu{150 ^\\circ C}$ = $\\pu{423 K}$ (glassy amorphous polymer). From Eq. 4.55 we estimate the activation energy as $ 10^{-3} E_D/R_g = \\left( 34.67/37.98 \\right)^2 \\left[ 7.5 - 2.5 \\times 10^{-4} (423 - 298)^{3/2} \\right] \\pm 1.0 = 5.96 \\pm 1.0 $ which gives $E_D = \\pu{49.6 kJ/mol} \\pm \\pu{8.3 kJ/mol}$. This value is higher than the experimentally observed value of $\\pu{32.2 kJ/mol}$ (Brandrup and Immergut, 1989). $ D_0 $ (in $\\pu{cm^2/s}$) is calculated from Eq. 4.57 as $ \\log D_0 = 0.96 \\pm 0.8 $. Finally, Eq. 4.53 gives the diffusivity at $\\pu{298 K}$ as $ D(298) = 10^{0.96} \\exp \\left( -5960/298 \\right) = \\pu{1.8 \\times 10^{-8} cm^2/s} $ which compares very well with the value given in Table 4.9.",
      "reference": "Example 4.6. Estimation of D",
      "keywords": [
        "diffusivity-estimation",
        "oxygen-polycarbonate",
        "activation-energy",
        "arrhenius-equation",
        "gas-transport"
      ],
