      "subtopic": "Renewable polymers and processability",
      "question": "Determine the time to degrade the HDPE and PS materials, whose properties are given in Table 11.8, to $M_w$ values of \\pu{420 g/mol} and \\pu{3120 g/mol} ($\\sim 30$ C-C bonds), respectively. In the case for HDPE use a temperature of \\pu{450 ^\\circ C}, while for PS use a temperature of \\pu{400 ^\\circ C}.",
      "options": {},
