      "type": "QA",
      "topic": "Practical Application and Technology",
      "originalTopic": "Practical application and technology",
      "subtopic": "Recycling and sustainability",
      "question": "A 40 mesh (meaning 40 openings per linear inch) screen of thickness $\\pu{1.04 mm}$ and diameter $\\pu{18.75 cm}$ is supported on a breaker plate and is used to filter sand and dirt from and produced by polypropylene (PP). The mass flow rate produced by the extrusion is $\\pu{12.5 kg/h}$. Estimate the initial (i.e., before accumulation of any sand) pressure drop across the screen for a PP in which the viscosity is described by the power-law model having parameters of $m = \\pu{3.21 \\times 10^4 Pa s^n}$ and $n = 0.25$, and $\\rho = \\pu{867 kg/m^3}$.",
      "options": {},
      "answer": [
        1786000.0,
        259.0
      ],
      "longAnswer": "Starting with Table 11.7 we can calculate the number of holes or openings in the screen of diameter \\pu{0.75 in.} and the size of the holes, which are assumed to be square. The number of holes is found by dividing the open area of the screen by the area of hole: (Screen area x void fraction)/hole area = (\\pu{0.375 in.})^2$\\pi$(0.66)/(\\pu{0.0165 in.})^2 = 1071 holes We can then calculate the volumetric flow rate per hole: ($\\pu{12.5 kg/h}$)/(1071 x $\\pu{867 kg/m^3}$) x ($\\pu{3600 s/h}$) = $\\pu{4 \\times 10^-9 m^3/s}$ The mean hydraulic radius, R_H, of the hole is R_H = (0.0165)^2/(4 \\times 0.0165) = $\\pu{4.125 \\times 10^-3 in.}$ = $\\pu{1.0478 \\times 10^-4 m}$ We now use Eq. 11.18 to solve for $\\Delta$ P: $\\Delta$ P = $\\langle$ v_z \\rangle^n (S + 3)^n 2m L/(2R_H)^(1+n) = (4 \\times 10^-9/1.6 \\times 10^-7)^0.25 1.626 \\times 2(3.21 \\times 10^4) 1.0414 \\times 10^-3/(2 \\times 10^-4)^1.25 = $\\pu{1.786 \\times 10^6 Pa}$ = $\\pu{259 psi}$",
      "reference": "Example 11.5. Estimate the Initial Pressure Drop Across a 40 Mesh Filter Screen",
      "keywords": [
        "filter-screen",
        "pressure-drop",
        "power-law-fluid",
        "mesh-screen",
        "breaker-plate",
        "reprocessing"
      ],
      "ability": [
        "calculation"
      ],
      "metrics": [
        "exact_match",
        "exact_match"
      ],
      "outputDescription": [
        "pressure drop",
        "pressure drop"
      ],
      "outputUnit": [
        "\\pu{Pa}",
        "\\pu{psi}"
      ],
      "images": []
