      "question": "For the recycle scheme shown in <image_1> and a table of recycle number shown in <image_2>, determine the age distribution of polymer (i.e., the fraction of material with one pass, two passes, and so on through the processing equipment) in the product stream for the following condition: $F_2 = \\pu{100 kg/h}$ (basis), $F_6 = \\pu{0 kg/h}$, $F_7 = \\pu{5 kg/h}$, $n = 4$. Report the mass flow rate (in $\\pu{kg/h}$) of material in the product stream $F_5$ that has made 1, 2, 3, and 4 passes through the processing equipment, respectively.",
