      "longAnswer": "We have $r = F_7/F_2 = 5/100 = 0.05$. From a mass balance on point A, $F_1 + F_7 = F_2$, and on the system, $F_1 = F_5 + F_6$, we find that $F_5 = \\pu{95 kg/h}$. From Table 11.4 the composition of the product stream is $F_5 = 95(0.95) + 95(0.0475) + 95(0.002375) + 95(0.00011875)$ $= 90.25 + 4.51 + 0.23 + 0.011 \\;\\pu{kg/h}$ Hence, after four passes through the processing equipment only 1.1\\% of the original material remains in the product stream. That means 95\\% of the material is essentially virgin material, only having passed through the processing equipment once.",
