      "subtopic": "Recycling and sustainability",
      "question": "The decay in tensile strength of an injection molded sample is given by the following equation: $P_i/P_{0i} = 1.0 - \\frac{P_0 - P_f}{20 P_0} i$ $\\quad$ (11.14) where $P_f = (1/5)P_0$ is the strength after 20 cycles of reprocessing the polymer, and after 20 cycles there is negligible change in the tensile strength. After 5 recycles of the polymer determine the percent of original properties for regrind ratios of 20\\% and 50\\% for the situation described in Table 11.4.",
      "options": {},
      "answer": [
        98.8,
        91
      ],
      "longAnswer": "Assuming Eq. 11.11 is valid for determining the tensile strength and using Table 11.4 for determining the weight fraction with given age or process history, we can write a general expression for the percent reduction in properties as $P_p = (1 - r)(1) + r(1 - r)(0.96) + r^2(1 - r)(0.92) + r^3(1 - r)(0.88) + r^4(1 - r)(0.84) + r^5(0.8)$ $\\quad$ (11.15) The numbers in parentheses result from evaluating Eq. 11.14. Now, for a recycle ratio of 0.2, the reduction in properties is only 1.2\\% or the polymer retains 98.8\\% of the original properties. For a recycle ratio of 0.5, 91\\% of the original properties are retained. Actually, after about 3 recycle steps, there is very little change in the properties.",
      "reference": "Example 11.4. Determination of the Percent of Original Properties for a Linear Decay in Properties",
