      "type": "QA",
      "topic": "Polymer Processing",
      "originalTopic": "Polymer Processing",
      "subtopic": "Extrusion",
      "question": "Poly(vinyl acetate) (PVAc) is extruded at $\\pu{180 ^\\circ C}$ at constant temperature through a capillary rheometer having a ram (reservoir) diameter of 0.375 in. and a capillary with an inside diameter of 0.041 in. and length of 0.622 in. The data provided give the efflux time to extrude 0.0737 in.3 at different ram loads. Using the following data in <image_1>, (a) Determine the power-law parameters n and m for PVAc and state all assumptions used to obtain your results. (b) Plot the apparent viscosity, $\\\\eta$, in units of Pa-s versus the nominal shear rate at the wall, $\\dot{\\gamma}_w$ (s$^{-1}$), using logarithmic coordinates.",
      "options": {},
      "answer": [
        0.2694,
        34600
      ],
      "longAnswer": "$\\Delta p = (\\text{ram load lb}_f) / (\\pi (0.375)^2 / 4) = \\text{ram load} / 0.110 \\pu{in psi}$ $\\tau_w = (R \\Delta p) / 2L = (0.041/2) / (2(0.622)) \\Delta p = 0.0165 \\Delta p \\pu{in psi}$ $Q = 0.0737 / \\text{efflux time} \\text{ in unit of }\\pu{in^3 min^{-1}}$ $\\phi = 4Q / (\\pi R^3) = 4Q / (\\pi (0.0205)^3) = 1.48 \\times 10^5 Q \\text{ in units of }\\pu{min^{-1}}$ A plot of $\\log \\tau_w$ versus $\\log \\phi$ will yield $n$ as the slope and $\\log m^{\\prime}$ as the intercept where $m^{\\prime} = m \\left( (3n+1) / 4n \\right)^n$ (eq 11.40) | $\\Delta p$ (psi) | $\\tau_w$ (psi) | $\\log \\tau_w$ | $Q$ (in$^3$ min$^{-1}$) | $\\phi$ (min$^{-1}$) | $\\log \\phi$ |\\n|---|---|---|---|---|---|\\n| 886 | 14.6 | 1.16 | 0.0139 | 2050 | 3.31 |\\n| 1318 | 21.7 | 1.34 | 0.0466 | 6890 | 3.84 |\\n| 1973 | 32.5 | 1.51 | 0.2377 | 35,100 | 4.55 |\\n| 2273 | 37.5 | 1.57 | 0.4335 | 64,100 | 4.81 | A least squares fit of the plot gives a slope ($n$) of 0.2694 and an intercept of 0.2829 ($m^{\\prime} = 1.92$). $m = 1.92 / (\\left( (3 \\times 0.269 + 1) / (4 \\times 0.269) \\right)^{0.269}) = 1.67 \\pu{psi-min^{0.269}} = 34,600 \\pu{Pa-s^{0.269}}$ The usual assumptions are fully-developed, isothermal, laminar, steady-state, and incompressible flow; negligible body forces, no slip at the wall, no viscous heating, and viscosity that is independent of pressure. (b) $\\dot{\\gamma}_w = (3n+1) / 4n\\phi$, $\\dot{\\gamma}_w = \\phi (3n+1) / 4n = 1.68 \\phi$ $\\eta = (\\tau_w) / (\\dot{\\gamma}_w)$ | $\\dot{\\gamma}_w$ (s$^{-1}$) | $\\eta$ (Pa-s) |\\n|---|---|\\n| 57.3 | 1750 |\\n| 193 | 774 |\\n| 983 | 228 |\\n| 1800 | 144 | Since $\\eta = m \\dot{\\gamma}_w^{n-1}$, $\\log \\eta = -0.728 \\log \\dot{\\gamma}_w + 4.53$ using values obtained from a least-squares fit ($R^2 = 0.9993$) of the four data points. The experimental data shows shear-thinning behavior over the range of wall shear rates from 57 to 1800 s$^{-1}$.",
