      "question": "If the number-average degree of polymerization for polystyrene obtained by the bulk polymerization of styrene at $\\pu{60 ^\\circ C}$ is $1000$, what would be the number-average degree of polymerization if the polymerization were conducted in a $\\pu{10\\%}$ solution in toluene ($\\pu{900 g}$ of toluene per $\\pu{100 g}$ of styrene) under otherwise identical conditions? The molecular weights of styrene and toluene are $104.12$ and $92.15$, respectively. The chain transfer constant $C$ for toluene with polystyrene is $1.25 \\times 10^{-5}$. State any assumptions that are needed.",
      "options": {},
