      "longAnswer": "$1 / \\bar{X}_n = 1 / ((\\bar{X}_n)_o) + C([SH]) / [M]$ Given: - $C = 1.25 \\times 10^{-5}$ - $(\\bar{X}_n)_o = 1000$ - $[M] = 100 / 104.12 = \\pu{0.9604 mol}$ - $[SH] = 900 / 92.15 = \\pu{9.767 mol}$ $1 / \\bar{X}_n = 1 / 1000 + (1.25 \\times 10^{-5})9.767 / 0.9604$ $1 / \\bar{X}_n = 0.001 + 1.27 \\times 10^{-4} = 1.127 \\times 10^{-3}$ $\\bar{X}_n = 887$",
