      "originalTopic": "Polymerization Synthesis",
      "subtopic": "Chain-growth polymerization",
      "question": "Styrene is polymerized by free-radical mechanism in solution. The initial monomer and initiator concentrations are $\\pu{1 M}$ (molar) and $\\pu{0.001 M}$, respectively. At the polymerization temperature of $\\pu{60 ^\\circ C}$, the initiator efficiency is $0.30$. The rate constants at the polymerization temperature are as follows: $k_d = \\pu{1.2 \\times 10^{-5} s^{-1}}$ $k_p = \\pu{176 M^{-1} s^{-1}}$ $k_t = \\pu{7.2 \\times 10^7 M^{-1} s^{-1}}$ Given this information, determine the following: (a) Rate of initiation at $\\pu{1 min}$ and at $\\pu{16.6 h}$ (b) Steady-state free-radical concentration at $\\pu{1 min}$ (c) Rate of polymerization at $\\pu{1 min}$ (d) Average free-radical lifetime, $\\tau$, at $\\pu{1 min}$, where $\\tau$ is defined as the radical concentration divided by the rate of termination (e) Number-average degree of polymerization at $\\pu{1 min}$",
      "options": {},
