      "question": "Poly(2,6-dimethyl-1,4-phenylene oxide) (PDMPO) can be partially crystallized in solution (i.e., solvent-induced crystallization). **Table 13-1 Representative van Krevelen Values for Molar Volume Increments (Bivalent Groups) at $\\pu{298 K}$** | Group | $V_{a,i}$ ($\\pu{cm^3/mol}$) | $V_{c,i}$ ($\\pu{cm^3/mol}$) | $V_w$ ($\\pu{cm^3/mol}$) |\\n|---|---|---|---|\\n| $\\ce{CH2}$ | 16.37 | 14.68 | 10.23 |\\n| $\\ce{CF2}$ | 23.7 | 21 | 14.8 |\\n| $\\ce{C(CH_3)_2}$ | 49.0 | 44.0 | 30.7 |\\n| $\\ce{-Si(CH_3)_2}$ | 67.5 | 60.6 | 42.2 |\\n| $\\ce{-CH(CH_3)-}$ | 32.72 | 29.35 | 20.45 |\\n| $\\ce{-CH(CN)-}$ | 30.7 | 27.5 | 21.5 |\\n| $\\ce{-CH(C_6H_5)-}$ | 84.16 | 75.48 | 52.6 |\\n| $\\ce{-CH=CH-}$ | 27.0 | 24.3 | 16.9 |\\n| $\\ce{-CH=CCl-}$ | 41.0 | 37.0 | 25.7 |\\n| $\\ce{-CH=C(CH_3)-}$ | *cis* 43 | 40 | 27.2 |\\n| | *trans* 43 | 37 | |\\n| $\\ce{-O-}$ | al 8.5 | (7.9) | (5.5) |\\n| | ar 8.0 | (7.1) | (5.0) |\\n| $\\ce{-COO-}$ | gen 23 | 21.5 | 15.2 |\\n| | acr 20.5 | 18.4 | |\\n| $\\ce{-OCOO-}$ | 31 | 27 | 18.9 |\\n| $p$-phenylene | 65.5 | 59 | 43.3 |\\n| 2,5-dimethyl-$p$-phenylene | 104 | 94 | 65.6 | Notes: al = aliphatic oxygen; ar = aromatic oxygen; gen = general; acr = acrylic. Values in parentheses are estimates. (a) Calculate the density of $\\pu{100\\%}$ crystalline PDMPO using the group contribution parameters given in Table 13-1. (b) If the crystallinity of a semicrystalline sample of PDMPO is $\\pu{8\\%}$, estimate its density using the relationship $V_{sc} = x_c V_c + (1 - x_c) V_a$ where $x_c$ is the degree of crystallinity, $V_c$ is the molar specific volume of a $\\pu{100\\%}$ crystalline polymer, and $V_a$ is the molar specific volume of the totally amorphous polymer.",
