      "id": "ded3c1b8-9288-4e6f-b14e-2d770ec52919",
      "dataset": "renzheng",
      "datasetLabel": "Certification Review",
      "type": "QA",
      "topic": "Basic Polymer Knowledge",
      "originalTopic": "Basic polymer knowledge",
      "subtopic": "Analysis",
      "question": "A sample of polystyrene is composed of a series of fractions of different-sized molecules: <image_1>. Calculate the number-average and weight-average molecular weights of this polymer sample.",
      "options": {},
      "answer": [
        32300,
        51760
      ],
      "longAnswer": "Polystyrene structure (for reference): - Monomer (styrene) SMILES: [START_SMILES]C=CC1=CC=CC=C1[END_SMILES] - Repeating unit SMILES: [START_SMILES]*CC(c1ccccc1)*[END_SMILES] Given weight fractions $w_i$ and molecular weights $M_i$: Weight-average molecular weight: $M_w$ = $\\sum_i$ $w_i$ $M_i$ = 0.10(12000) + 0.19(21000) + 0.24(35000) + 0.18(49000) + 0.11(73000) + 0.08(102000) + 0.06(122000) + 0.04(146000) = 51760 So, $M_w$ = \\pu{51760 g mol^{-1}}. Number-average molecular weight (using weight fractions): $M_n$ = (1)/($\\sum_i$ \\left($w_i$/$M_i$\\right)) $\\sum_i$ \\left($w_i$/$M_i$\\right) = 0.10/12000 + 0.19/21000 + 0.24/35000 + 0.18/49000 + 0.11/73000 + 0.08/102000 + 0.06/122000 + 0.04/146000 $\\approx$ 3.096$\\times$ 10^{-5} $M_n$ $\\approx$ (1)/(3.096$\\times$ 10^{-5}) $\\approx$ 32300 So, $M_n$ = \\pu{32300 g mol^{-1}}.",
      "reference": "page_37, problem_1-7",
