      "originalTopic": "Polymerization Synthesis",
      "subtopic": "Chain-growth polymerization",
      "question": "Assume that 1.0 $\\times$ 10^{-}^{3} mol of sodium naphthalene is dissolved in tetrahydrofuran and then 2.0 mol of styrene is introduced into the system by rapid injection. The final solution volume is 1 L, and instantaneous homogeneous mixing occurs. Half of the monomer is polymerized in 2000 s. Calculate the propagation rate constant. Calculate the degree of polymerization at 2000 s and at 4000 s of reaction time.",
      "options": {},
      "answer": [
        0.347,
        0.002,
        0.003
      ],
      "longAnswer": "a) $R_p$ = -d$[M]$/dt = $k_p$[M^{-}]$[M]$ Assume [M^{-}] = concentration of initiator. -∫ d$[M]$/$[M]$ = $k_p$[M^{-}] ∫ dt = 1.0 $\\times$ 10^{-}^{3} $k_p$ (t - t_{0}) - ln($[M]$/$[M]$_{0}) = 1.0 $\\times$ 10^{-}^{3} $k_p$ (2000) - ln(1/2) = 1.0 $\\times$ 10^{-}^{3} $k_p$ (2000) $k_p$ = 0.347 L mol^{-}^{1} s^{-}^{1} b) $\\bar{X}_n$ = 2($[M]$_{0} - $[M]$)/[M^{-}] = 2(2 - 1)/(1.0 $\\times$ 10^{-}^{3}) = 2.0 $\\times$ 10^{-}^{3} c) For 4000 s: - ln($[M]$/$[M]$_{0}) = 1.0 $\\times$ 10^{-}^{3} (0.347)(4000) = 1.388 $[M]$ = $[M]$_{0} / e^{1.388} = $[M]$_{0} / 4 $[M]$_{0} - $[M]$ = 2 - 2/4 = 1.5 $\\bar{X}_n$ = 2(1.5)/(1.0 $\\times$ 10^{-}^{3}) = 3.0 $\\times$ 10^{-}^{3}",
      "reference": "page_462, problem_5-10",
