      "originalTopic": "Polymerization techniques",
      "subtopic": "Heterogeneous",
      "question": "Quantitatively compare the rate and degree of polymerization of styrene polymerized in bulk at \\pu{60 ^\\circ C} with an emulsion polymerization (case 2 behavior: n̄ = 0.5) containing 1.0 $\\times$ 10^15 polymer particles per milliliter. Assume that $[M]$ = 5.0 molar, Rᵢ = 5.0 $\\times$ 10^12 radicals per milliliter per second, and all rate constants are the same for both systems. For each polymerization system, indicate the various ways (if any) by which the polymerization rate can be affected without affecting the degree of polymerization.",
      "options": {},
      "answer": [
        0.01,
        0.01
      ],
      "longAnswer": "The ratio of polymerization rates is \\[ ((R_p)_{\\text{bulk}})/((R_p)_{\\text{emulsion}}) = (k_p[M]\\left(R_i/2k_t\\right)^{1/2})/((10^3\\bar{n}Nk_p[M])/(N_A)) = (\\left(R_i/2k_t\\right)^{1/2} N_A)/(10^3\\bar{n}N) \\] Substituting numerical values, \\[ ((R_p)_{\\text{bulk}})/((R_p)_{\\text{emulsion}}) = (\\left((5.0\\times10^{12}\\times10^3)/(6.022\\times10^{23}\\times2\\times6.0\\times10^7)\\right)^{1/2}(6.022\\times10^{23}))/(10^3(1.0\\times10^{15})^{0.5}) = 1.0\\times10^{-2} \\] The ratio of number-average degrees of polymerization is \\[ ((\\bar{X}_n)_{\\text{bulk}})/((\\bar{X}_n)_{\\text{emulsion}}) = ((2k_p[M])/((2R_i k_t)^{1/2}))/(Nk_p[M]/R_i) = (2\\left(R_i/2k_t\\right)^{1/2})/(N) \\] Substituting values, \\[ ((\\bar{X}_n)_{\\text{bulk}})/((\\bar{X}_n)_{\\text{emulsion}}) = (2\\left((5.0\\times10^{12}\\times10^3)/(6.022\\times10^{23}\\times2\\times6.0\\times10^7)\\right)^{1/2})/((10^3(1.0\\times10^{15}))/(6.022\\times10^{23})) = 1.0\\times10^{-2} \\] In both calculations it is necessary to make the needed conversions to express N and $R_i$ into units of mol L^-1 and mol L^-1 s^-1, respectively. The emulsion polymerization proceeds with a rate 100 times faster than the bulk polymerization and yields a polymer whose molecular weight is 100 times larger. Note that the molecular weight calculation assumes the absence of chain transfer. The separate control of rate and molecular weight in bulk or other homogeneous polymerizations is very limited. Changing the initiation rate affects the rate and molecular weight in opposite directions. For example, increasing the concentration of initiator or using a more reactive initiator results in higher polymerization rate, but lower polymer molecular weight. The effect of temperature varies with the type of initiation. Higher temperature increases rate but lowers molecular weight when initiation occurs by thermal decomposition of an initiator such as AIBN or peroxide. Redox polymerization proceeds with increased rate and very little effect on molecular weight. Photochemical polymerization proceeds with small increases in rate and molecular weight with increasing temperature. For emulsion polymerization, increasing N results in increases in both polymerization rate and polymer molecular weight. One can vary the rate without affecting molecular weight by varying N while keeping N/$R_i$ constant. Alternately, molecular weight can be varied at constant polymerization rate by varying N/$R_i$ at constant N.",
