      "subtopic": "molecular weight determination",
      "question": "Isobutylene is polymerized under conditions where chain transfer to monomer is the predominant chain-breaking reaction. A \\pu{4.0 g} sample of the polymer was found to decolorize \\pu{6.0 mL} of a \\pu{0.01 M} solution of bromine in carbon tetrachloride. Calculate the number-average molecular weight of the polyisobutylene.",
      "options": {},
      "answer": [
        66700.0
      ],
      "longAnswer": "There is one double-bond end group per polymer molecule because chain transfer to monomer is the only mode of termination. The number of moles of polymer molecules equals the number of moles of bromine decolorized: \\[ \\text{mol polymer} = \\text{mol Br}_2 = (\\pu{0.006 L})(\\pu{0.01 mol L^{-1}}) = \\pu{6e-5 mol} \\] The number-average molecular weight is then \\[ M_n = (\\pu{4.0 g})/(\\pu{6e-5 mol}) = \\pu{6.67e4 g mol^{-1}} \\]",
